package net.civeira.phylax.features.access.tenantloginprovider.application.visibility;

import lombok.Getter;
import lombok.NonNull;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.common.security.InvocationSource;
import net.civeira.phylax.common.security.OperationContext;
import net.civeira.phylax.features.access.tenantloginprovider.domain.TenantLoginProvider;

@Getter
public class TenantLoginProviderAccesibleCheck {

  /**
   * @autogenerated AccesibleCheckGenerator
   */
  @NonNull
  private final OperationContext context;

  /**
   * @autogenerated AccesibleCheckGenerator
   */
  private final TenantLoginProvider entity;

  /**
   * @autogenerated AccesibleCheckGenerator
   */
  @NonNull
  private Boolean visible;

  /**
   * @autogenerated AccesibleCheckGenerator
   * @param context
   * @param entity
   */
  public TenantLoginProviderAccesibleCheck(final OperationContext context,
      final TenantLoginProvider entity) {
    this.context = context;
    this.entity = entity;
    this.visible = true;
  }

  /**
   * @autogenerated AccesibleCheckGenerator
   * @return
   */
  public Actor getActor() {
    return this.context.getActor();
  }

  /**
   * @autogenerated AccesibleCheckGenerator
   * @return
   */
  public InvocationSource getSource() {
    return this.context.getSource();
  }

  /**
   * @autogenerated AccesibleCheckGenerator
   */
  public void hide() {
    this.visible = false;
  }
}
